CREATE TABLE IF NOT EXISTS "__EFMigrationsHistory" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
);

START TRANSACTION;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260923235326_Init') THEN
    CREATE TABLE "Genres" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Name" text NOT NULL,
        CONSTRAINT "PK_Genres" PRIMARY KEY ("Id")
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260923235326_Init') THEN
    CREATE TABLE "Movies" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Title" text NOT NULL,
        "Description" text NOT NULL,
        "ReleaseYear" integer NOT NULL,
        "PosterUrl" text,
        "GenreId" integer NOT NULL,
        CONSTRAINT "PK_Movies" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_Movies_Genres_GenreId" FOREIGN KEY ("GenreId") REFERENCES "Genres" ("Id") ON DELETE CASCADE
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260923235326_Init') THEN
    CREATE TABLE "Reviews" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Author" text NOT NULL,
        "Text" text NOT NULL,
        "Rating" integer NOT NULL,
        "MovieId" integer NOT NULL,
        CONSTRAINT "PK_Reviews" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_Reviews_Movies_MovieId" FOREIGN KEY ("MovieId") REFERENCES "Movies" ("Id") ON DELETE CASCADE
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260923235326_Init') THEN
    CREATE INDEX "IX_Movies_GenreId" ON "Movies" ("GenreId");
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260923235326_Init') THEN
    CREATE INDEX "IX_Reviews_MovieId" ON "Reviews" ("MovieId");
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260923235326_Init') THEN
    INSERT INTO "__EFMigrationsHistory" ("MigrationId", "ProductVersion")
    VALUES ('20260923235326_Init', '10.0.12');
    END IF;
END $EF$;
COMMIT;

START TRANSACTION;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261018220848_MovieGenresManyToMany') THEN
    CREATE TABLE "MovieGenres" (
        "GenresId" integer NOT NULL,
        "MoviesId" integer NOT NULL,
        CONSTRAINT "PK_MovieGenres" PRIMARY KEY ("GenresId", "MoviesId"),
        CONSTRAINT "FK_MovieGenres_Genres_GenresId" FOREIGN KEY ("GenresId") REFERENCES "Genres" ("Id") ON DELETE CASCADE,
        CONSTRAINT "FK_MovieGenres_Movies_MoviesId" FOREIGN KEY ("MoviesId") REFERENCES "Movies" ("Id") ON DELETE CASCADE
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261018220848_MovieGenresManyToMany') THEN
    CREATE INDEX "IX_MovieGenres_MoviesId" ON "MovieGenres" ("MoviesId");
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261018220848_MovieGenresManyToMany') THEN
    INSERT INTO "MovieGenres" ("GenresId", "MoviesId")
    SELECT "GenreId", "Id"
    FROM "Movies";
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261018220848_MovieGenresManyToMany') THEN
    ALTER TABLE "Movies" DROP CONSTRAINT "FK_Movies_Genres_GenreId";
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261018220848_MovieGenresManyToMany') THEN
    DROP INDEX "IX_Movies_GenreId";
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261018220848_MovieGenresManyToMany') THEN
    ALTER TABLE "Movies" DROP COLUMN "GenreId";
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261018220848_MovieGenresManyToMany') THEN
    INSERT INTO "__EFMigrationsHistory" ("MigrationId", "ProductVersion")
    VALUES ('20261018220848_MovieGenresManyToMany', '10.0.12');
    END IF;
END $EF$;
COMMIT;

